cKQ0tkzH1Bx2xf6nHihjrLQMedRDVOkEJ3A==","shasum":"d651736b1aac6f7962dd31160b2b1fac8e771a27","tarball":"https://registry.npmjs.org/pi-adaptive-thinking/-/pi-adaptive-thinking-0.1.1.tgz","fileCount":7,"unpackedSize":172338,"attestations":{"url":"https://registry.npmjs.org/-/npm/v1/attestations/pi-adaptive-thinking@0.1.1","provenance":{"predicateType":"https://slsa.dev/provenance/v1"}},"signatures":[{"keyid":"SHA256:DhQ8wR5APBvFHLF/+Tc+AYvPOdTpcIDqOhxsBHRwC7U","sig":"MEUCIQC3pE07oe5yA/xlhdaBv3y5CYGKf1U3rfkTPYEuLiWizQIgMBtrS+5fBLFb7hDHf6K6Oz8ySL71T03U4h32sPs1BMc="}]},"_npmUser":{"name":"GitHub Actions","email":"npm-oidc-no-reply@github.com","trustedPublisher":{"id":"github","oidcConfigId":"oidc:1e2c39a1-4699-4dd0-8d68-de21548ff633"}},"directories":{},"maintainers":[{"name":"ianpascoe_","email":"ian.g.pascoe@gmail.com"}],"_npmOperationalInternal":{"host":"s3://npm-registry-packages-npm-production","tmp":"tmp/pi-adaptive-thinking_0.1.1_1779840295355_0.3577540885519026"},"_hasShrinkwrap":false}},"time":{"created":"2026-05-26T18:05:15.357Z","modified":"2026-05-27T00:04:55.856Z","0.0.0":"2026-05-26T18:05:15.613Z","0.1.0":"2026-05-26T18:19:43.733Z","0.1.1":"2026-05-27T00:04:55.533Z"},"bugs":{"url":"https://github.com/ian-pascoe/pi-adaptive-thinking/issues"},"author":{"name":"Ian Pascoe"},"license":"MIT","homepage":"https://github.com/ian-pascoe/pi-adaptive-thinking#readme","keywords":["adaptive-thinking","pi","pi-package","reasoning","thinking"],"repository":{"type":"git","url":"git+https://github.com/ian-pascoe/pi-adaptive-thinking.git"},"description":"Pi Adaptive Thinking extension","maintainers":[{"name":"ianpascoe_","email":"ian.g.pascoe@gmail.com"}],"readme":"<div align=\"center\">\n\n# pi-adaptive-thinking\n\nBring adaptive reasoning-effort control to Pi agents.\n\n</div>\n\n`pi-adaptive-thinking` is a Pi extension that lets the agent change Pi's thinking level through a tool named `set_thinking_level`.\n\nIt mirrors the user-facing behavior of `opencode-adaptive-thinking` while using Pi-native APIs: `pi.getThinkingLevel()`, `pi.setThinkingLevel()`, and `thinking_level_select`.\n\n## Installation\n\n```bash\npi install npm:pi-adaptive-thinking\n```\n\nFor local development:\n\n```bash\npnpm install\npnpm build\npi -e ./dist/index.js\n```\n\n## Behavior\n\nThe extension registers a tool with these parameters:\n\n- `level`: one of the valid Pi thinking levels for the current model.\n- `persist`: optional boolean, default `false`.\n\nTemporary changes:\n\n```json\n{ \"level\": \"high\", \"persist\": false }\n```\n\nThis changes thinking level for the current agent turn and restores the prior/baseline level when the turn ends.\n\nPersistent changes:\n\n```json\n{ \"level\": \"low\", \"persist\": true }\n```\n\nThis changes the session baseline until another persistent change is made or the user changes thinking level manually.\n\n## Configuration\n\nConfiguration files are loaded in this order:\n\n1. Project: `.pi/adaptive-thinking.json`\n2. Global: `~/.pi/agent/adaptive-thinking.json`\n3. Built-in defaults\n\nProject configuration takes precedence over global configuration.\n\n```json\n{\n  \"enabled\": true,\n  \"quiet\": false,\n  \"toolName\": \"set_thinking_level\",\n  \"toolDescription\": \"Set your thinking level\",\n  \"systemPrompt\": \"You MUST manage thinking level actively. Lower it before trivial or routine turns; raise it for ambiguity, debugging, risky changes, or multi-step synthesis. Reassess at turn start, after meaningful new evidence, and when the task shifts. NEVER leave the current level unchanged by inertia, and NEVER reply to a trivial turn before considering a downshift.\"\n}\n```\n\n## Development\n\n```bash\npnpm install\npnpm format:check\npnpm lint\npnpm typecheck\npnpm test\npnpm build\n```\n\nRun all checks:\n\n```bash\npnpm verify\n```\n","readmeFilename":"README.md"}
