def _fit_context(payload: dict[str, Any], max_bytes: int) -> dict[str, Any]:
    payload = json.loads(json.dumps(payload, ensure_ascii=False))
    payload["context_truncated"] = False
    while (
        len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > max_bytes
        and payload.get("recent_tasks")
    ):
        payload["recent_tasks"].pop()
        payload["context_truncated"] = True
    while (
        len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > max_bytes
        and payload.get("recent_messages")
    ):
        payload["recent_messages"].pop(0)
        payload["context_truncated"] = True
    return payload


