) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise SemanticRoutingError(f"{label} 必须是 object")
    required = {"skill", "score", "mode", "workflow"}
    if set(value) != required:
        raise SemanticRoutingError(f"{label} 字段必须精确为 {sorted(required)}")
    skill = value.get("skill")
    if not isinstance(skill, str) or skill not in allowed_skills:
        raise SemanticRoutingError(f"{label}.skill 不在当前加载面")
    score = value.get("score")
    if (
        not isinstance(score, (int, float))
        or isinstance(score, bool)
        or not 0 <= float(score) <= 1
    ):
        raise SemanticRoutingError(f"{label}.score 必须在 [0, 1] 范围内")
    for key in ("mode", "workflow"):
        if value.get(key) is not None and not isinstance(value.get(key), str):
            raise SemanticRoutingError(f"{label}.{key} 必须是 string 或 null")
        if isinstance(value.get(key), str) and len(value[key]) > 80:
            raise SemanticRoutingError(f"{label}.{key} 最多 80 个字符")
    if value.get("mode") in INTERACTION_MODES:
        raise SemanticRoutingError(
            f"{label}.mode 不得使用 interaction_mode；应使用领域 mode 或 null"
        )
    return {
        "skill": skill,
        "score": float(score),
        "mode": value.get("mode"),
        "workflow": value.get("workflow"),
    }


def validate_model_result(
    payload: dict[str, Any],
    *,
    available_skills: set[str],
    internal_skills: set[str],
) -> dict[str, Any]:
    required = {
        "schema_version",
        "decision",
        "complexity",
        "interaction_mode",
        "primary",
        "alternatives",
        "needs_clarification",
        "clarification_question",
        "missing_context",
        "pending_handoff",
        "reason_codes",
    }
    if set(payload) != required:
        raise SemanticRoutingError(
            "semantic routing result 字段必须精确为 " + ", ".join(sorted(required))
        )
    if payload.get("schema_version") != 1:
        raise SemanticRoutingError("semantic routing result schema_version 必须为 1")
    decision = payload.get("decision")
    if decision not in {"answer", "route", "clarify"}:
        raise SemanticRoutingError("semantic routing result decision 无效")
    if payload.get("complexity") not in {"simple", "complex"}:
        raise SemanticRoutingError("semantic routing result complexity 无效")
    mode = payload.get("interaction_mode")
    if mode is not None and mode not in INTERACTION_MODES:
        raise SemanticRoutingError("semantic routing result interaction_mode 无效")
    allowed = set(available_skills) - set(internal_skills)
    primary = _validate_candidate(
        payload.get("primary"),
        label="primary",
        allowed_skills=allowed,
    )
    alternatives_raw = payload.get("alternatives")
    if not isinstance(alternatives_raw, list) or len(alternatives_raw) > 3:
        raise SemanticRoutingError("alternatives 必须是最多 3 项的 array")
    alternatives = [
        _validate_candidate(item, label=f"alternatives[{index}]", allowed_skills=allowed)
        for index, item in enumerate(alternatives_raw)
    ]
    candidate_skills = [primary["skill"], *(item["skill"] for item in alternatives)]
    if len(candidate_skills) != len(set(candidate_skills)):
        raise SemanticRoutingError("primary 与 alternatives 的 skill 不得重复")
    needs_clarification = payload.get("needs_clarification")
    if not isinstance(needs_clarification, bool):
        raise SemanticRoutingError("needs_clarification 必须是 boolean")
    question = payload.get("clarification_question")
    if question is not None and not isinstance(question, str):
        raise SemanticRoutingError("clarification_question 必须是 string 或 null")
    if isinstance(question, str) and len(question) > 500:
        raise SemanticRoutingError("clarification_question 最多 500 个字符")
    missing_context = payload.get("missing_context")
    if not isinstance(missing_context, list) or not all(
        isinstance(item, str) and item.strip() for item in missing_context
    ):
        raise SemanticRoutingError("missing_context 必须是非空 string 组成的 array")
    if len(missing_context) > 5 or any(len(item) > 200 for item in missing_context):
        raise SemanticRoutingError("missing_context 最多 5 项且每项最多 200 个字符")
    reason_codes = payload.get("reason_codes")
    if not isinstance(reason_codes, list) or not reason_codes or not all(
        isinstance(item, str) and REASON_CODE_RE.fullmatch(item)
        for item in reason_codes
    ):
        raise SemanticRoutingError("reason_codes 必须是合法的非空 string array")
    if len(reason_codes) > 10 or any(len(item) > 64 for item in reason_codes):
        raise SemanticRoutingError("reason_codes 最多 10 项且每项最多 64 个字符")
    if decision == "answer":
        if primary["skill"] != "wb-chat" or needs_clarification or question is not None:
            raise SemanticRoutingError("answer 必须由 wb-chat 承接且不追问")
    elif decision == "route":
        if primary["skill"] == "wb-chat" or needs_clarification or question is not None:
            raise SemanticRoutingError("route 必须选择非 wb-chat owner 且不追问")
        if missing_context:
            raise SemanticRoutingError("route 不得携带阻断性 missing_context")
    else:
        if not needs_clarification or not isinstance(question, str) or not question.strip():
            raise SemanticRoutingError("clarify 必须包含一个 clarification_question")

    pending = payload.get("pending_handoff")
    if pending is not None:
        if not isinstance(pending, dict):
            raise SemanticRoutingError("pending_handoff 必须是 object 或 null")
        pending_fields = {"skill", "mode", "workflow", "gate", "reason"}
        if set(pending) != pending_fields:
            raise SemanticRoutingError("pending_handoff 字段不符合契约")
        if pending.get("skill") not in allowed:
            raise SemanticRoutingError("pending_handoff.skill 不在当前加载面")
        if pending.get("gate") not in {"none", "confirmation", "explicit-request"}:
            raise SemanticRoutingError("pending_handoff.gate 无效")
        for key in ("mode", "workflow"):
            if pending.get(key) is not None and not isinstance(pending.get(key), str):
                raise SemanticRoutingError(f"pending_handoff.{key} 必须是 string 或 null")
            if isinstance(pending.get(key), str) and len(pending[key]) > 80:
                raise SemanticRoutingError(f"pending_handoff.{key} 最多 80 个字符")
        if pending.get("mode") in INTERACTION_MODES:
            raise SemanticRoutingError(
                "pending_handoff.mode 不得使用 interaction_mode"
            )
        if not isinstance(pending.get("reason"), str) or not pending["reason"].strip():
            raise SemanticRoutingError("pending_handoff.reason 不能为空")
        if len(pending["reason"]) > 500:
            raise SemanticRoutingError("pending_handoff.reason 最多 500 个字符")

    return {
        **payload,
        "primary": primary,
        "alternatives": alternatives,
        "missing_context": [item.strip() for item in missing_context],
        "reason_codes": list(reason_codes),
    }


def parse_model_result(
    raw: str,
    *,
    available_skills: set[str],
    internal_skills: set[str],
) -> dict[str, Any]:
    return validate_model_result(
        _json_object(raw),
        available_skills=available_skills,
        internal_skills=internal_skills,
    )


def _contains_any(text: str, values: set[str]) -> bool:
    lowered = normalize_phrase(text)
    return any(value in lowered for value in values)


def _is_confirmation(text: str) -> bool:
    normalized = normalize_phrase(text)
    return normalized in CONFIRMATION_PHRASES or any(
        phrase in normalized for phrase in ("按上面的", "按照上面的", "同意这个方案")
    )


def _is_continuation(text: str) -> bool:
    return normalize_phrase(text) in CONTINUATION_PHRASES


def _is_lightweight_answer(text: str) -> bool:
    normalized = normalize_phrase(text)
    if normalized in CASUAL_PHRASES:
        return True
    if (
        WORKBENCH_SKILL_RE.search(normalized)
        and _contains_any(normalized, WORKBENCH_META_SIGNALS)
        and not _contains_any(normalized, EXECUTION_SIGNALS)
        and not any(
            value in normalized for value in ("报错", "异常", "失败", "为什么")
        )
    ):
        return True
    if not LIGHTWEIGHT_QUESTION_RE.search(normalized):
        return False
